    case 4:
      if (lookahead == ',') ADVANCE(19);
      if (lookahead == '.') ADVANCE(14);
      if (lookahead == ':') ADVANCE(29);
      if (lookahead == '=') ADVANCE(28);
      if (lookahead == '}') ADVANCE(20);
